"""Editor documentation derived from the same catalog used by checks."""

from typing import Any

from smelt.config.schema import config_json_schema as model_json_schema
from smelt.rules.registry import build_rule_set

SCHEMA_COMMENT = (
    "Generated by Smelt. Refresh with `smelt config schema`; not used by the checker."
)


def config_json_schema() -> dict[str, Any]:
    schema = model_json_schema()
    schema["$comment"] = SCHEMA_COMMENT
    properties: dict[str, Any] = {}
    codes: dict[str, Any] = {}
    source_properties: dict[str, Any] = {}
    source_codes: dict[str, Any] = {}
    for rule in build_rule_set().rules:
        doc = rule.explain()
        definition = {
            "type": "string",
            "enum": ["error", "warning", "hint", "off"],
            "title": f"{rule.code}: {doc.summary}",
            "description": f"{doc.summary} {doc.rationale} Repair: {doc.fix}",
            "markdownDescription": (
                f"**{rule.code} — {rule.name}**\n\n{doc.summary}\n\n{doc.rationale}"
                f"\n\n**Problem**\n```{doc.example_language}\n{doc.bad}\n```"
                f"\n\n**Preferred**\n```{doc.example_language}\n{doc.good}\n```"
                f"\n\n{doc.fix}\n\nRun `smelt explain {rule.name}` for details."
            ),
            "examples": [rule.default_severity.value],
        }
        properties[rule.name] = definition
        codes[f"^{rule.code}$"] = definition
        if getattr(rule, "scope", "source") == "source":
            source_properties[rule.name] = definition
            source_codes[f"^{rule.code}$"] = definition
    rule_settings = {
        "type": "object",
        "description": "Explicit checks by problem name or stable SMT code. Each value both enables the check and sets severity; off disables it.",
        "properties": properties,
        "patternProperties": codes,
        "additionalProperties": False,
    }
    schema["$defs"]["RuleSettings"] = rule_settings
    schema["$defs"]["SourceRuleSettings"] = {
        **rule_settings,
        "description": "Source rules use the same names and severities. Test-file and project checks belong in the project rules map.",
        "properties": source_properties,
        "patternProperties": source_codes,
    }
    schema["properties"]["rules"] = {"$ref": "#/$defs/RuleSettings"}
    schema["$defs"]["PackageContract"]["properties"]["rules"] = {
        "$ref": "#/$defs/SourceRuleSettings"
    }
    return schema
